mapper.select:
SELECT distinct nui.id, nui.news_content, nui.type, nui.been_read, nui.sender_id, nui.recipient_id, nui.works_id, nui.works_content, nui.works_parent_id, nui.works_parent_uid, nui.prn_news_works_id, um.nickname as senderName, um.avatar as senderAvatar, nui.create_time FROM `b_news_user_info` AS nui LEFT JOIN b_user_main AS um ON nui.sender_id = um.uuid
nui.type=#{bo.type} and nui.recipient_id=#{bo.recipientId}
and nui.been_read=#{bo.beenRead}
order by create_time desc
